class ShoppingCart {
  constructor() {
    this.items = [];
    this.discount = 0;
  }

  addItem(name, price, quantity) {
    // Validate before touching state so a bad call can't corrupt an existing item.
    if (typeof price !== 'number' || !Number.isFinite(price)) {
      throw new TypeError('Price must be a finite number');
    }
    if (price < 0) {
      throw new RangeError('Price cannot be negative');
    }
    if (typeof quantity !== 'number' || Number.isNaN(quantity)) {
      throw new TypeError('Quantity must be a number');
    }
    if (!Number.isInteger(quantity) || quantity <= 0) {
      throw new RangeError('Quantity must be a positive integer');
    }

    const existing = this.items.find(i => i.name === name);
    if (existing) {
      existing.quantity += quantity;
    } else {
      this.items.push({ name, price, quantity });
    }
  }

  // Returns true if the item was removed, false if it wasn't in the cart.
  removeItem(name) {
    const before = this.items.length;
    this.items = this.items.filter(i => i.name !== name);
    return this.items.length < before;
  }

  getTotal() {
    let total = 0;
    for (let i = 0; i < this.items.length; i++) {
      total += this.items[i].price * this.items[i].quantity;
    }
    return total - (total * this.discount / 100);
  }

  applyDiscount(percent) {
    if (typeof percent !== 'number' || !Number.isFinite(percent)) {
      throw new TypeError('Discount must be a finite number');
    }
    if (percent < 0 || percent > 100) {
      throw new RangeError('Discount must be between 0 and 100');
    }
    this.discount = percent;
  }

  getItemCount() {
    return this.items.length;
  }
}

module.exports = ShoppingCart;

